import { Cart, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: This event represents when the user invoked the checkout and not viewing the first step of the checkout. This should be sent even if the back-end service reuses an existing checkout identifier.
*/
export type BeginCheckout = {
    events: Array<Cart | Identity | PartyIdentification | ErrorEvent>;
}

export class BeginCheckoutBuilder {

    private beginCheckout: BeginCheckout = {
        events: []
    }

    private cart!: Cart;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : BeginCheckoutBuilder {
        this.cart = cart;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : BeginCheckoutBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : BeginCheckoutBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : BeginCheckoutBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : BeginCheckout {
        if(this.cart) {
            this.beginCheckout.events.push(this.cart);
        }
        if(this.errorEvent) {
            this.beginCheckout.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.beginCheckout.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.beginCheckout.events.push(this.partyIdentification);
        }

        return this.beginCheckout;
    }
}
